WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_train_person'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '过人问题', 'kp-trv-train-person', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "火车过人问题"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "人是一个没有长度的点。火车开过人，走过的总路程 = 火车的全长。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“一列火车长 200 米，经过一个站在路边的行人……”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "1. 人静止：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 火车长 L = V火 × T"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "2. 人迎面走(相遇)：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 火车长 L = (V火 + V人) × T"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "3. 人同向走(追及)：", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 火车长 L = (V火 - V人) × T"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[判断人的运动状态] --> B{人动不动?怎么动?}\nB -- 不动 --> C[S = V火 × T]\nB -- 迎面来 --> D[S = (V火 + V人) × T]\nB -- 同向跑 --> E[S = (V火 - V人) × T]\nC --> F[此处的 S 永远等于火车的长度 L!]"}}]}$$ AS jsonb), NULL, '过人问题的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "过人问题"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_train_person", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
